def fmt(a, b, c):
    return '\n'.join(str(len(x)) + ' ' + ' '.join(map(str, x)) for x in (a, b, c))

def sarr(rng, n, lo, hi):
    return sorted(rng.randint(lo, hi) for _ in range(n))

def gen(rng):
    t = [fmt([1], [1], [1]), fmt([1, 2, 3], [4, 5], [6]), fmt([1, 1, 1], [1, 1], [1]), fmt([1, 4, 7], [2, 4, 8], [3, 4, 9]),
         fmt([-5, -5, 0], [-5, 0, 0, 3], [3, 3, 3]), fmt([7], [1, 2, 3], [-4, -3]), fmt([-10**9, 10**9], [-10**9, 0], [10**9])]
    for n in (1, 2, 3, 5, 8, 12):
        for _ in range(3):
            r = rng.choice([3, 8, 30])
            t.append(fmt(sarr(rng, rng.randint(1, n), -r, r), sarr(rng, rng.randint(1, n), -r, r), sarr(rng, rng.randint(1, n), -r, r)))
    N = 10**5
    M = 10**9
    t.append(fmt(sarr(rng, N, -M, M), sarr(rng, N, -M, M), sarr(rng, N, -M, M)))
    t.append(fmt(sarr(rng, N, 0, 50), sarr(rng, N, 0, 50), sarr(rng, N, 0, 50)))
    t.append(fmt([5] * N, [5] * N, [5] * N))
    t.append(fmt(list(range(0, 3 * N, 3)), list(range(1, 3 * N, 3)), list(range(2, 3 * N, 3))))
    return t
